module.exports = function () {
  let starts = 0
  return {
    id: 'badstopplugin',
    name: 'Bad Stop Plugin',
    schema: function () {
      return { type: 'object', properties: {} }
    },
    start: function () {
      starts++
    },
    stop: function () {
      throw new Error('stop failed')
    },
    statusMessage: function () {
      return 'started ' + starts
    }
  }
}
